window.DEVICES={"generated":"2026-11-05","devices":[{"id":"ads1115","part":"ADS1115","kind":"16-bit delta-sigma ADC with PGA","vendor":"Texas Instruments","summary":"A 16-bit I2C analog-to-digital converter with four inputs, a programmable gain stage and selectable data rates. You pick the input pair, range and speed in the Config register, then read the result.","source":{"doc":"SBAS444E","rev":"December 2024","url":"https://www.ti.com/lit/ds/symlink/ads1115.pdf","sha256":"eefff4d412ce2dcd7e659f47238edc9b2fa02e5971f2625af730502033701834","bytes":2654255,"pages":57},"bus":"i2c","addresses":[{"strap":"ADDR to GND","addr":"0x48","bin":"1001000"},{"strap":"ADDR to VDD","addr":"0x49","bin":"1001001"},{"strap":"ADDR to SDA","addr":"0x4A","bin":"1001010"},{"strap":"ADDR to SCL","addr":"0x4B","bin":"1001011"}],"addressCite":{"p":20,"q":"GND 1001000b VDD 1001001b SDA 1001010b SCL 1001011b"},"registers":[{"addr":"0x00","name":"Conversion","access":"R","reset":"0x0000","cite":{"p":24,"q":"Conversion Register (P[1:0] = 00b) [reset = 0000h]"}},{"addr":"0x01","name":"Config","access":"R/W","reset":"0x8583","cite":{"p":25,"q":"Config Register (P[1:0] = 01b) [reset = 8583h]"}},{"addr":"0x02","name":"Lo_thresh","access":"R/W","reset":"0x8000","cite":{"p":27,"q":"Lo_thresh (P[1:0] = 10b) [reset = 8000h]"}},{"addr":"0x03","name":"Hi_thresh","access":"R/W","reset":"0x7FFF","cite":{"p":27,"q":"Hi_thresh (P[1:0] = 11b) [reset = 7FFFh]"}}],"facts":[{"id":"pointer","text":"The first byte after the address selects which register the next read or write uses.","cite":{"p":24,"all":["00b : Conversion register 01b : Config register","10b : Lo_thresh register 11b : Hi_thresh register"]}},{"id":"byte-order","text":"Register bytes go out most significant byte first.","cite":{"p":20,"q":"Register bytes are sent with the most significant byte first"}},{"id":"pga","text":"Config bits 11:9 pick the full-scale range, six real ranges; codes 5 to 7 all mean +-0.256 V. Default is +-2.048 V.","cite":{"p":26,"all":["000b : FSR = ±6.144V","001b : FSR = ±4.096V","010b : FSR = ±2.048V","011b : FSR = ±1.024V","100b : FSR = ±0.512V","101b : FSR = ±0.256V","110b : FSR = ±0.256V","111b : FSR = ±0.256V"]}},{"id":"lsb","text":"The size of one count follows the range: 187.5 uV at +-6.144 V down to 7.8125 uV at +-0.256 V.","cite":{"p":15,"all":["±6.144V(1) 187.5μV","±4.096V(1) 125μV","±2.048V 62.5μV","±1.024V 31.25μV","±0.512V 15.625μV","±0.256V 7.8125μV"]}},{"id":"mux","text":"Config bits 14:12 choose the input pair: four differential and four single-ended (against GND).","cite":{"p":25,"all":["000b : AINP = AIN0 and AINN = AIN1","001b : AINP = AIN0 and AINN = AIN3","010b : AINP = AIN1 and AINN = AIN3","011b : AINP = AIN2 and AINN = AIN3","100b : AINP = AIN0 and AINN = GND","101b : AINP = AIN1 and AINN = GND","110b : AINP = AIN2 and AINN = GND","111b : AINP = AIN3 and AINN = GND"]}},{"id":"dr","text":"Config bits 7:5 choose the data rate from 8 to 860 samples per second; default 128.","cite":{"p":26,"all":["000b : 8SPS","001b : 16SPS","010b : 32SPS","011b : 64SPS","100b : 128SPS","101b : 250SPS","110b : 475SPS","111b : 860SPS"]}},{"id":"codes","text":"Output codes: +full scale clips at 0x7FFF, zero is 0x0000, -full scale and below clip at 0x8000.","cite":{"p":23,"all":["(215 – 1)/215 7FFFh","0 0000h","≤ –FS 8000h"]}},{"id":"single-shot","text":"In single-shot mode (MODE=1) writing OS=1 starts one conversion; OS reads 0 while it runs and 1 when done.","cite":{"p":25,"all":["1b : Start a single conversion (when in power-down state)","0b : Device is currently performing a conversion."]}},{"id":"continuous","text":"Writing 0 to the MODE bit switches to continuous conversion.","cite":{"p":18,"q":"To switch to continuous-conversion mode, write a 0b to the MODE bit"}},{"id":"conv-time","text":"One conversion takes 1 / data-rate seconds (derived, not stated).","derived":true,"cite":{"p":15,"q":"Use the DR[2:0] bits in the Config register to select output data rates"}}],"fsr":[6.144,4.096,2.048,1.024,0.512,0.256,0.256,0.256],"lsbUv":[187.5,125,62.5,31.25,15.625,7.8125,7.8125,7.8125],"sps":[8,16,32,64,128,250,475,860],"mux":[[0,1],[0,3],[1,3],[2,3],[0,-1],[1,-1],[2,-1],[3,-1]],"notModeled":["The comparator, the ALERT/RDY pin and the Lo_thresh/Hi_thresh behavior (the registers store values only)","The OS bit in continuous mode (reads as 1 here)","Offset, gain error, noise and input-impedance loading","ADS1113 and ADS1114 (this is the ADS1115 only)"],"inputs":[{"id":"ain0","label":"AIN0","unit":"V","min":0,"max":3.3,"step":0.001,"default":1.65},{"id":"ain1","label":"AIN1","unit":"V","min":0,"max":3.3,"step":0.001,"default":0.5},{"id":"ain2","label":"AIN2","unit":"V","min":0,"max":3.3,"step":0.001,"default":2.5},{"id":"ain3","label":"AIN3","unit":"V","min":0,"max":3.3,"step":0.001,"default":3.3}],"sample":"// ADS1115 at 0x48 (ADDR tied to GND): read AIN0 against GND, +-4.096 V range, one-shot\nconst ADDR = 0x48;\n// OS=1 (start), MUX=100 (AIN0/GND), PGA=001 (+-4.096 V), MODE=1 (single-shot), DR=100 (128 SPS), comparator off\nconst cfg = (1 << 15) | (0b100 << 12) | (0b001 << 9) | (1 << 8) | (0b100 << 5) | 0b11;\ni2c.writeReg16(ADDR, 0x01, cfg);\ndelay(10); // 128 SPS is about 7.8 ms per conversion\n\nlog('Config now =', hex(i2c.readReg16(ADDR, 0x01)), '(bit 15 set = conversion finished)');\nconst code = toInt16(i2c.readReg16(ADDR, 0x00));\nlog('code =', code, '->', (code * 125e-6).toFixed(4), 'V  (125 uV per count at +-4.096 V)');\n"},{"id":"ina219","part":"INA219","kind":"High-side current and power monitor","vendor":"Texas Instruments","summary":"An I2C monitor that measures the voltage across a shunt resistor and the bus voltage. After you program a calibration value it also reports current and power directly.","source":{"doc":"SBOS448G","rev":"December 2015","url":"https://www.ti.com/lit/ds/symlink/ina219.pdf","sha256":"58004eda854d07478e6fc6f4398c114f60a3bcf18d4877471c7c1a306d1fa1cb","bytes":892731,"pages":38},"bus":"i2c","addresses":[{"strap":"A1=GND A0=GND","addr":"0x40","bin":"1000000"},{"strap":"A1=GND A0=VS+","addr":"0x41","bin":"1000001"},{"strap":"A1=GND A0=SDA","addr":"0x42","bin":"1000010"},{"strap":"A1=GND A0=SCL","addr":"0x43","bin":"1000011"},{"strap":"A1=VS+ A0=GND","addr":"0x44","bin":"1000100"},{"strap":"A1=VS+ A0=VS+","addr":"0x45","bin":"1000101"},{"strap":"A1=VS+ A0=SDA","addr":"0x46","bin":"1000110"},{"strap":"A1=VS+ A0=SCL","addr":"0x47","bin":"1000111"},{"strap":"A1=SDA A0=GND","addr":"0x48","bin":"1001000"},{"strap":"A1=SDA A0=VS+","addr":"0x49","bin":"1001001"},{"strap":"A1=SDA A0=SDA","addr":"0x4A","bin":"1001010"},{"strap":"A1=SDA A0=SCL","addr":"0x4B","bin":"1001011"},{"strap":"A1=SCL A0=GND","addr":"0x4C","bin":"1001100"},{"strap":"A1=SCL A0=VS+","addr":"0x4D","bin":"1001101"},{"strap":"A1=SCL A0=SDA","addr":"0x4E","bin":"1001110"},{"strap":"A1=SCL A0=SCL","addr":"0x4F","bin":"1001111"}],"addressCite":{"p":14,"all":["GND GND 1000000","GND VS+ 1000001","GND SDA 1000010","GND SCL 1000011","VS+ GND 1000100","VS+ VS+ 1000101","VS+ SDA 1000110","VS+ SCL 1000111","SDA GND 1001000","SDA VS+ 1001001","SDA SDA 1001010","SDA SCL 1001011","SCL GND 1001100","SCL VS+ 1001101","SCL SDA 1001110","SCL SCL 1001111"]},"registers":[{"addr":"0x00","name":"Configuration","access":"R/W","reset":"0x399F","cite":{"p":19,"q":"Configuration Register (address = 00h) [reset = 399Fh]"}},{"addr":"0x01","name":"Shunt voltage","access":"R","reset":"0x0000","cite":{"p":18,"q":"01 Shunt voltage Shunt voltage measurement data."}},{"addr":"0x02","name":"Bus voltage","access":"R","reset":"0x0000","cite":{"p":18,"q":"02 Bus voltage Bus voltage measurement data."}},{"addr":"0x03","name":"Power","access":"R","reset":"0x0000","cite":{"p":23,"q":"Power Register (address = 03h) [reset = 00h]"}},{"addr":"0x04","name":"Current","access":"R","reset":"0x0000","cite":{"p":23,"q":"Current Register (address = 04h) [reset = 00h]"}},{"addr":"0x05","name":"Calibration","access":"R/W","reset":"0x0000","cite":{"p":23,"q":"Calibration Register (address = 05h) [reset = 00h]"}}],"facts":[{"id":"shunt-lsb","text":"The shunt voltage register counts in 10 microvolt steps.","cite":{"p":12,"q":"Shunt Voltage LSB of 10 μV"}},{"id":"bus-lsb","text":"The bus voltage register counts in 4 mV steps, after shifting right by three bits.","cite":{"p":23,"q":"(decimal = 8000, hex = 1F40), and LSB = 4 mV"}},{"id":"bus-shift","text":"The bus voltage value sits in bits 15 to 3; shift right by three before applying the 4 mV step.","cite":{"p":12,"q":"must be shifted right by three bits"}},{"id":"cal-formula","text":"Calibration = trunc(0.04096 / (Current_LSB x Rshunt)).","cite":{"p":12,"q":"Cal = trunc 0.04096 Current_LSB"}},{"id":"power-lsb","text":"The power register's step is fixed at 20 times Current_LSB.","cite":{"p":12,"q":"Power_LSB = 20 Current_LSB"}},{"id":"current-eq","text":"Current register = shunt register x calibration / 4096.","cite":{"p":12,"q":"Current Register 4096"}},{"id":"power-eq","text":"Power register = current register x bus register / 5000.","cite":{"p":12,"q":"Power Register 5000"}},{"id":"worked-example","text":"The datasheet's worked example (20 mV across 2 mOhm, 12 V bus, 1 mA/bit) gives calibration 20480, shifted bus value 2995, current 10000 and power 5990. The simulator reproduces all four.","cite":{"p":26,"all":["results in a calibration value of 20480 (5000h)","equal to BB3h, the decimal equivalent of 2995","the result of 10000 (2710h) is automatically loaded","the result of 5990 (1766h) is automatically loaded"]}},{"id":"cal-fs0","text":"Bit 0 of the Calibration register is not used in the calculation.","cite":{"p":23,"q":"bit FS0 is not used in the calculation"}},{"id":"reset-bit","text":"Writing 1 to Configuration bit 15 resets every register to its default; the bit clears itself.","cite":{"p":19,"q":"Resets all registers to default values; this bit self-clears."}},{"id":"brng","text":"Configuration bit 13 picks the bus range: 0 is 16 V, 1 is 32 V (default).","cite":{"p":19,"q":"0 = 16V FSR 1 = 32V FSR (default value)"}},{"id":"pga","text":"Configuration bits 12:11 set the shunt PGA: /1 is +-40 mV, /2 +-80 mV, /4 +-160 mV, /8 +-320 mV (default).","cite":{"p":19,"all":["0 0 1 ±40 mV","0 1 /2 ±80 mV","1 0 /4 ±160 mV","1 1 /8 ±320 mV"]}}],"pga":[40,80,160,320],"notModeled":["ADC resolution, averaging and conversion time: registers follow the inputs immediately","Operating modes (power-down, triggered): the MODE bits are stored but ignored","The CNVR and OVF flags in the bus voltage register (always read as 0 here)","Offset, gain error and noise"],"inputs":[{"id":"vbus","label":"Bus voltage","unit":"V","min":0,"max":32,"step":0.004,"default":12},{"id":"iload","label":"Load current","unit":"A","min":-3,"max":3.2,"step":0.001,"default":1},{"id":"rshunt","label":"Shunt resistor","unit":"ohm","min":0.01,"max":1,"step":0.01,"default":0.1}],"sample":"// INA219 with A1=A0=GND (0x40) and a 0.1 ohm shunt\nconst ADDR = 0x40, RSHUNT = 0.1;\n// Pick a scale: up to 3.2 A, so Current_LSB = 3.2 / 2^15 ~ 100 uA.\nconst currentLsb = 0.0001;\nconst cal = Math.trunc(0.04096 / (currentLsb * RSHUNT));\ni2c.writeReg16(ADDR, 0x05, cal);\nlog('Calibration =', cal, '(' + hex(cal) + ')');\n\nconst shunt = toInt16(i2c.readReg16(ADDR, 0x01)) * 10e-6;      // volts\nconst vbus = (i2c.readReg16(ADDR, 0x02) >> 3) * 0.004;         // volts\nconst amps = toInt16(i2c.readReg16(ADDR, 0x04)) * currentLsb;\nconst watts = i2c.readReg16(ADDR, 0x03) * 20 * currentLsb;\nlog('shunt', (shunt * 1000).toFixed(2), 'mV | bus', vbus.toFixed(3), 'V');\nlog('current', amps.toFixed(4), 'A | power', watts.toFixed(3), 'W');\n"},{"id":"ina226","part":"INA226","kind":"Bidirectional current and power monitor","vendor":"Texas Instruments","summary":"An I2C monitor like the INA219 but with finer steps: 2.5 microvolts on the shunt and 1.25 mV on the bus, plus alert registers and two identification registers.","source":{"doc":"SBOS547C","rev":"August 2026 (as printed on the document)","url":"https://www.ti.com/lit/ds/symlink/ina226.pdf","sha256":"c9b67f886d4a5241a5e070723f7b61867409eeb27eed768b9cdd9cb17e03ca2d","bytes":1516957,"pages":41},"bus":"i2c","addresses":[{"strap":"A1=GND A0=GND","addr":"0x40","bin":"1000000"},{"strap":"A1=GND A0=VS","addr":"0x41","bin":"1000001"},{"strap":"A1=GND A0=SDA","addr":"0x42","bin":"1000010"},{"strap":"A1=GND A0=SCL","addr":"0x43","bin":"1000011"},{"strap":"A1=VS A0=GND","addr":"0x44","bin":"1000100"},{"strap":"A1=VS A0=VS","addr":"0x45","bin":"1000101"},{"strap":"A1=VS A0=SDA","addr":"0x46","bin":"1000110"},{"strap":"A1=VS A0=SCL","addr":"0x47","bin":"1000111"},{"strap":"A1=SDA A0=GND","addr":"0x48","bin":"1001000"},{"strap":"A1=SDA A0=VS","addr":"0x49","bin":"1001001"},{"strap":"A1=SDA A0=SDA","addr":"0x4A","bin":"1001010"},{"strap":"A1=SDA A0=SCL","addr":"0x4B","bin":"1001011"},{"strap":"A1=SCL A0=GND","addr":"0x4C","bin":"1001100"},{"strap":"A1=SCL A0=VS","addr":"0x4D","bin":"1001101"},{"strap":"A1=SCL A0=SDA","addr":"0x4E","bin":"1001110"},{"strap":"A1=SCL A0=SCL","addr":"0x4F","bin":"1001111"}],"addressCite":{"p":18,"all":["GND GND 1000000","GND VS 1000001","GND SDA 1000010","GND SCL 1000011","VS GND 1000100","VS VS 1000101","VS SDA 1000110","VS SCL 1000111","SDA GND 1001000","SDA VS 1001001","SDA SDA 1001010","SDA SCL 1001011","SCL GND 1001100","SCL VS 1001101","SCL SDA 1001110","SCL SCL 1001111"]},"registers":[{"addr":"0x00","name":"Configuration","access":"R/W","reset":"0x4127","cite":{"p":22,"all":["00h Configuration Register","01000001 00100111 4127 R/ W"]}},{"addr":"0x01","name":"Shunt voltage","access":"R","reset":"0x0000","cite":{"p":22,"q":"01h Shunt Voltage Register Shunt voltage measurement data. 00000000 00000000 0000 R"}},{"addr":"0x02","name":"Bus voltage","access":"R","reset":"0x0000","cite":{"p":22,"q":"02h Bus Voltage Register Bus voltage measurement data. 00000000 00000000 0000 R"}},{"addr":"0x03","name":"Power","access":"R","reset":"0x0000","cite":{"p":22,"all":["03h Power Register(2)","being delivered to the load. 00000000 00000000 0000 R"]}},{"addr":"0x04","name":"Current","access":"R","reset":"0x0000","cite":{"p":22,"all":["04h Current Register(2)","flowing through the shunt resistor. 00000000 00000000 0000 R"]}},{"addr":"0x05","name":"Calibration","access":"R/W","reset":"0x0000","cite":{"p":22,"all":["05h Calibration Register","Overall system calibration. 00000000 00000000 0000 R/ W"]}},{"addr":"0x06","name":"Mask/Enable","access":"R/W","reset":"0x0000","cite":{"p":22,"q":"06h Mask/Enable Register Alert configuration and Conversion Ready flag. 00000000 00000000 0000 R/ W"}},{"addr":"0x07","name":"Alert Limit","access":"R/W","reset":"0x0000","cite":{"p":22,"all":["07h Alert Limit Register","selected Alert function. 00000000 00000000 0000 R/ W"]}},{"addr":"0xFE","name":"Manufacturer ID","access":"R","reset":"0x5449","cite":{"p":22,"q":"FEh Manufacturer ID Register Contains unique manufacturer identification number. 0101010001001001 5449 R"}},{"addr":"0xFF","name":"Die ID","access":"R","reset":"0x2260","cite":{"p":22,"q":"FFh Die ID Register Contains unique die identification number."}}],"facts":[{"id":"shunt-lsb","text":"The shunt voltage register counts in 2.5 microvolt steps.","cite":{"p":5,"q":"Shunt voltage 2.5 μV Bus voltage 1.25 mV"}},{"id":"bus-lsb","text":"The bus voltage register counts in 1.25 mV steps with no bit shift.","cite":{"p":16,"q":"fixed 1.25mV/bit"}},{"id":"cal-formula","text":"Calibration = 0.00512 / (Current_LSB x Rshunt), truncated to an integer.","cite":{"p":15,"q":"CAL = 0.00512 Current_LSB × RSHUNT"}},{"id":"power-lsb","text":"The power register's step is fixed at 25 times Current_LSB.","cite":{"p":26,"q":"internally programmed to equal 25 times the programmed value of the Current_LSB"}},{"id":"current-eq","text":"Current register = shunt register x calibration / 2048.","cite":{"p":15,"q":"Current = ShuntVoltage × CalibrationRegister 2048 (3)"}},{"id":"power-eq","text":"Power register = current register x bus register / 20000.","cite":{"p":16,"q":"Power = Current × BusVoltage 20000 (4)"}},{"id":"worked-example","text":"The datasheet's worked example (20 mV shunt, 12 V bus, 1 mA/bit, 2 mOhm) gives shunt 8000, bus 9584, cal 2560, current 10000 and power 4792. The simulator reproduces all five.","cite":{"p":16,"all":["Step 2 Shunt Register 01h 1F40h 8000 2.5μV 20mV","Step 3 Bus Voltage Register 02h 2570h 9584 1.25mV 11.98V","Step 4 Calibration Register 05h A00h 2560","Step 5 Current Register 04h 2710 10000 1mA 10A","Step 6 Power Register 03h 12B8h 4792 25mW 119.82W"]}},{"id":"bus-msb","text":"The top bit of the bus voltage register is always zero, since the pin only measures positive voltage.","cite":{"p":16,"q":"the MSB of the Bus Voltage Register (02h) is always zero"}},{"id":"no-cal","text":"Current and power read zero until the Calibration register is programmed.","cite":{"p":22,"q":"default to '0' because the Calibration register defaults to '0'"}}],"notModeled":["Conversion times, averaging and operating modes: registers follow the inputs immediately","The reset bit in Configuration, the alert function and the ALERT pin (Mask/Enable and Alert Limit are plain storage)","Offset, gain error and noise"],"inputs":[{"id":"vbus","label":"Bus voltage","unit":"V","min":0,"max":36,"step":0.00125,"default":12},{"id":"iload","label":"Load current","unit":"A","min":-10,"max":10,"step":0.001,"default":10},{"id":"rshunt","label":"Shunt resistor","unit":"ohm","min":0.001,"max":0.1,"step":0.001,"default":0.002}],"sample":"// INA226 at 0x40 with a 2 mOhm shunt, scaled for up to 32.768 A (1 mA per count)\nconst ADDR = 0x40, RSHUNT = 0.002, currentLsb = 0.001;\nlog('Manufacturer ID =', hex(i2c.readReg16(ADDR, 0xFE)), ' Die ID =', hex(i2c.readReg16(ADDR, 0xFF)));\n\nconst cal = Math.trunc(0.00512 / (currentLsb * RSHUNT));\ni2c.writeReg16(ADDR, 0x05, cal);\nlog('Calibration =', cal, '(' + hex(cal) + ')');\n\nconst vshunt = toInt16(i2c.readReg16(ADDR, 0x01)) * 2.5e-6;\nconst vbus = i2c.readReg16(ADDR, 0x02) * 1.25e-3;\nconst amps = toInt16(i2c.readReg16(ADDR, 0x04)) * currentLsb;\nconst watts = i2c.readReg16(ADDR, 0x03) * 25 * currentLsb;\nlog('shunt', (vshunt * 1000).toFixed(3), 'mV | bus', vbus.toFixed(3), 'V');\nlog('current', amps.toFixed(3), 'A | power', watts.toFixed(2), 'W');\n"},{"id":"tmp117","part":"TMP117","kind":"Digital temperature sensor","vendor":"Texas Instruments","summary":"A 16-bit I2C temperature sensor. One register holds the result, one holds configuration and flags, two hold alert limits, and one identifies the chip.","source":{"doc":"SNOSD82D","rev":"September 2022","url":"https://www.ti.com/lit/ds/symlink/tmp117.pdf","sha256":"78212e91e478035a91165397a8de8a90bfc776759dc445243c033537f0c4b789","bytes":1717888,"pages":50},"bus":"i2c","addresses":[{"strap":"ADD0 to GND","addr":"0x48"},{"strap":"ADD0 to V+","addr":"0x49"},{"strap":"ADD0 to SDA","addr":"0x4A"},{"strap":"ADD0 to SCL","addr":"0x4B"}],"addressCite":{"p":21,"q":"1001000x Ground 1001001x V+ 1001010x SDA 1001011x SCL"},"registers":[{"addr":"0x00","name":"Temp_Result","access":"R","reset":"0x8000","cite":{"p":25,"q":"00h R 8000h Temp_Result Temperature result register"}},{"addr":"0x01","name":"Configuration","access":"R/W","reset":"0x0220","cite":{"p":25,"q":"01h R/W 0220h(1) Configuration Configuration register"}},{"addr":"0x02","name":"THigh_Limit","access":"R/W","reset":"0x6000","cite":{"p":25,"q":"02h R/W 6000h(1) THigh_Limit Temperature high limit register"}},{"addr":"0x03","name":"TLow_Limit","access":"R/W","reset":"0x8000","cite":{"p":25,"q":"03h R/W 8000h(1) TLow_Limit"}},{"addr":"0x0F","name":"Device_ID","access":"R","reset":"0x0117","cite":{"p":25,"q":"0Fh R 0117h Device_ID Device ID register"}}],"facts":[{"id":"lsb","text":"One count of the result register is 7.8125 milli-degrees C; the value is two's complement.","cite":{"p":26,"q":"One LSB equals 7.8125 m°C"}},{"id":"after-reset","text":"Until the first conversion finishes after a reset, the result register reads -256 C (0x8000).","cite":{"p":26,"q":"the temperature register reads –256 °C until the first conversion"}},{"id":"data-ready","text":"Data_Ready (Configuration bit 13) is cleared by reading either the Configuration or the result register.","cite":{"p":14,"q":"read the configuration register or the temperature result register to clear the Data_Ready flag"}},{"id":"high-alert","text":"HIGH_Alert (bit 15) is set when a result is above the high limit.","cite":{"p":27,"q":"Set when the conversion result is higher than the high limit"}},{"id":"low-alert","text":"LOW_Alert (bit 14) is set when a result is below the low limit.","cite":{"p":27,"q":"Set when the conversion result is lower than the low limit"}},{"id":"alert-clear","text":"The high and low alert flags clear when the Configuration register is read.","cite":{"p":27,"q":"Cleared on read of configuration register"}},{"id":"cycle-default","text":"The reset configuration (CONV=100) gives a one-second conversion cycle at any averaging setting.","cite":{"p":28,"q":"100 1 s 1 s 1 s 1 s"}},{"id":"soft-reset","text":"Writing 1 to Soft_Reset (bit 1) resets the device; the bit always reads back 0.","cite":{"p":28,"q":"triggers software reset with a duration of 2 ms"}},{"id":"conv-time","text":"One conversion takes about 15.5 ms typical; averaging repeats it, so the first result arrives after avg x 15.5 ms (derived, not stated).","derived":true,"cite":{"p":6,"q":"Conversion time One-shot mode 13 15.5 17.5 ms"}}],"cycleTable":{"cite":{"p":28,"all":["000 15.5 ms 125 ms 500 ms 1 s","001 125 ms 125 ms 500 ms 1 s","010 250 ms 250 ms 500 ms 1 s","011 500 ms 500 ms 500 ms 1 s","100 1 s 1 s 1 s 1 s","101 4 s 4 s 4 s 4 s","110 8 s 8 s 8 s 8 s","111 16 s 16 s 16 s 16 s"]},"ms":[[15.5,125,500,1000],[125,125,500,1000],[250,250,500,1000],[500,500,500,1000],[1000,1000,1000,1000],[4000,4000,4000,4000],[8000,8000,8000,8000],[16000,16000,16000,16000]]},"notModeled":["One-shot and shutdown modes (the MOD bits are stored but ignored)","EEPROM registers, temperature offset and the ALERT pin","Thermal (therm) alert mode: only alert mode is modeled","Noise, accuracy and self-heating: the sensor returns exactly the temperature you set, rounded to one count"],"inputs":[{"id":"temp","label":"Temperature","unit":"C","min":-40,"max":125,"step":0.0078125,"default":25}],"sample":"// TMP117 on I2C address 0x48 (ADD0 tied to GND)\nconst ADDR = 0x48;\nlog('Device ID =', hex(i2c.readReg16(ADDR, 0x0F)));\n\ndelay(200); // first result after a reset takes a while (see the data-ready flag)\nconst cfg = i2c.readReg16(ADDR, 0x01);\nlog('Config =', hex(cfg), (cfg & 0x2000) ? '(data ready)' : '(not ready yet)');\n\nconst raw = toInt16(i2c.readReg16(ADDR, 0x00));\nlog('raw =', raw, '->', (raw * 0.0078125).toFixed(4), 'C');\n"}]};
